import{_ as n,C as t,c as s,o as i,aa as l,G as a}from"./chunks/framework.Cn7WEiMX.js";const u=JSON.parse('{"title":"物品集","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/ExcellentEnchants/features/item-sets.md","filePath":"wiki/ExcellentEnchants/features/item-sets.md"}'),c={name:"wiki/ExcellentEnchants/features/item-sets.md"};function p(_,e,h,m,E,d){const r=t("NolebaseGitContributors"),o=t("NolebaseGitChangelog");return i(),s("div",null,[e[0]||(e[0]=l('<h1 id="物品集" tabindex="-1">物品集 <a class="header-anchor" href="#物品集" aria-label="Permalink to &quot;物品集&quot;">​</a></h1> <p>在 ExcellentEnchants 中，你可以创建自定义附魔的物品集。这些套装会用在附魔配置中，用于设置附魔可用的<a href="https://zh.minecraft.wiki/w/%E9%AD%94%E5%92%92%E5%AE%9A%E4%B9%89%E6%A0%BC%E5%BC%8F" target="_blank" rel="noreferrer">初级物品</a>和<a href="https://zh.minecraft.wiki/w/%E9%AD%94%E5%92%92%E5%AE%9A%E4%B9%89%E6%A0%BC%E5%BC%8F" target="_blank" rel="noreferrer">次级物品</a>。</p> <p>你可以在 <strong>item_types.yml</strong> 中自定义物品集。默认情况下它包含了所有附魔适用的盔甲、工具及武器。</p> <h2 id="格子" tabindex="-1">格子 <a class="header-anchor" href="#格子" aria-label="Permalink to &quot;格子&quot;">​</a></h2> <p>物品集配置中的 <code>Slots</code> 决定了附魔生效的<a href="https://jd.papermc.io/paper/1.21.5/org/bukkit/inventory/EquipmentSlot.html" target="_blank" rel="noreferrer">槽位</a>。</p> <p>例如，默认的 <code>helmet</code> 物品集分配了 <code>HEAD</code> 格子。这表示头盔附魔只会在玩家将其装备至这个格子（头盔栏）时生效。但是，你可以将其他格子加入配置中，让附魔物品支持在更多格子上生效。</p> ',12)),a(r),a(o)])}const b=n(c,[["render",p]]);export{u as __pageData,b as default};
